{"tool":"sandbox","code":"use std::fs;
use std::path::Path;

const SEED: u64 = 0x243F_6A88_85A3_08D3; // fixed seed constant
const COUNT: usize = 20_000_000;
const OUT_DIR: &str = "/work/artifacts";
const OUT_FILE: &str = "/work/artifacts/result.json";

// SplitMix64 PRNG (fixed constants: gamma = golden ratio, standard mix constants).
struct SplitMix64 {
    state: u64,
}

impl SplitMix64 {
    fn new(seed: u64) -> Self {
        SplitMix64 { state: seed }
    }

    fn next_u64(&mut self) -> u64 {
        self.state = self.state.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    fn next_u32(&mut self) -> u32 {
        (self.next_u64() >> 32) as u32
    }
}

// Order-independent checksum: wrapping sum of all values as u64.
fn wrapping_sum(data: &[u32]) -> u64 {
    let mut acc: u64 = 0;
    for &v in data {
        acc = acc.wrapping_add(v as u64);
    }
    acc
}

// Second order-independent integrity check: XOR fold.
fn xor_fold(data: &[u32]) -> u64 {
    let mut acc: u64 = 0;
    for &v in data {
        acc ^= v as u64;
    }
    acc
}

// FNV-1a 64-bit over the little-endian byte serialization of the values in order.
fn fnv1a_values(data: &[u32]) -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for &v in data {
        for b in v.to_le_bytes() {
            hash ^= b as u64;
            hash = hash.wrapping_mul(0x0000_0100_0000_01B3);
        }
    }
    hash
}

// Sortedness: each element <= next element.
fn is_sorted(data: &[u32]) -> bool {
    for i in 1..data.len() {
        if data[i - 1] > data[i] {
            return false;
        }
    }
    true
}

fn main() {
    // 1) Generate 20,000,000 pseudo-random u32 values from seeded SplitMix64.
    let mut rng = SplitMix64::new(SEED);
    let mut data: Vec<u32> = Vec::with_capacity(COUNT); // 20M * 4 B = 80 MB
    for _ in 0..COUNT {
        data.push(rng.next_u32());
    }
    assert_eq!(data.len(), COUNT, "generated count mismatch");

    // 2) Checksums before sorting (order-independent, so they must survive sorting).
    let sum_before = wrapping_sum(&data);
    let xor_before = xor_fold(&data);

    // 3) Sort in place (no extra allocation for u32).
    data.sort_unstable();

    // 4) Recompute checksums after sorting; equality proves the multiset survived.
    let sum_after = wrapping_sum(&data);
    let xor_after = xor_fold(&data);
    assert_eq!(sum_before, sum_after, "checksum changed across sort");
    assert_eq!(xor_before, xor_after, "xor checksum changed across sort");

    // 5) Sortedness and count assertions.
    assert!(is_sorted(&data), "data not sorted after sort_unstable");
    assert_eq!(data.len(), COUNT, "count mismatch after sort");

    // 6) Statistics. Count is even (20,000,000), so the median is the average of
    //    the elements at indices 9,999,999 and 10,000,000, computed as u64
    //    (floor of the mean; no overflow since each value fits in u32).
    let min: u32 = data[0];
    let max: u32 = data[COUNT - 1];
    let median: u64 = ((data[COUNT / 2 - 1] as u64) + (data[COUNT / 2] as u64)) / 2;

    assert!(min <= max, "min > max after sort");
    assert!(
        (min as u64) <= median && median <= (max as u64),
        "median outside [min, max]"
    );

    // FNV-1a over the sorted values (order-dependent, so computed post-sort).
    let fnv_sorted = fnv1a_values(&data);

    // 7) Hand-built JSON; every field is numeric, so no escaping is needed.
    let json = format!(
        "{{\"count\":{},\"min\":{},\"max\":{},\"median\":{},\"checksum\":{},\"fnv1a\":{},\"seed\":{}}}",
        COUNT, min, max, median, sum_after, fnv_sorted, SEED
    );

    // 8) Ensure the output directory exists, then write the file.
    fs::create_dir_all(OUT_DIR).expect("failed to create /work/artifacts");
    assert!(Path::new(OUT_DIR).is_dir(), "/work/artifacts is not a directory");
    fs::write(OUT_FILE, json.as_bytes()).expect("failed to write result.json");

    // 9) Verify the file on disk matches exactly what we intended to write.
    let read_back = fs::read(OUT_FILE).expect("failed to read back result.json");
    assert!(!read_back.is_empty(), "result.json is empty");
    assert_eq!(read_back, json.as_bytes(), "result.json content mismatch");

    // 10) Result JSON to stdout; short status summary to stderr.
    println!("{}", json);
    eprintln!(
        "OK: generated and sorted {} u32 values (seed={:#018x}); result.json written and verified byte-for-byte",
        COUNT, SEED
    );
}
","summary":"Rust 2024 std-only program: SplitMix64 (fixed seed 0x243F6A8885A308D3) generates 20,000,000 u32 values into one 80 MB Vec, sorts in place with sort_unstable, asserts count==20000000, full sortedness, min<=median<=max, and pre/post-sort checksum equality (wrapping u64 sum plus XOR fold); computes median as u64 average of elements at indices 9,999,999 and 10,000,000 and an FNV-1a 64 hash of the sorted bytes; creates /work/artifacts if missing, writes result.json (count, min, max, median, checksum, fnv1a, seed), reads it back and asserts byte-for-byte equality, prints the JSON to stdout and a status line to stderr."}

